{"results": [{"id": "hp_doc_c85eef658c7c850731a716f69c669f32f1c2427c066738224cb7a19db24a2f5f", "title": "Number 23 Basketball Player", "text": "Number 23 Basketball Player is a sculpture by Niki de Saint Phalle.", "score": 26.5442}, {"id": "hp_doc_ae371c9a631c6c44d7da408e7f5e9ce03a0e61c260205304f22e8a43bb1fc6c0", "title": "Casey Jacobsen", "text": "Casey Gardner Jacobsen (born March 19, 1981) is an American retired professional basketball player. He had an extensive European basketball career, mostly playing for Brose Baskets. There he won the German League Championship in 2007 and 2010 by receiving the German League Finals MVP Award and further Championships in 2011, 2012 and 2013. Also he the German Cup with Bamberg in the years 2010, 2011 and 2012. Following his retirement in 2014, Brose Baskets retired his jersey number 23.", "score": 16.0989}, {"id": "hp_doc_6ae393fe6515300e590a278bdbf6044ed9b8278e66e39d535c0c5dfb60fd5a08", "title": "Remo Bianco", "text": "Remo Bianco, birth name Remo Bianchi, (3 June 1922 – 23 February 1988) was an Italian painter and sculptor.", "score": 15.2085}], "remaining_searches": 2}
