{"results": [{"id": "hp_doc_5dfab43fb29aa9bd1c17cde39437ba0c45bf211831ea39d936b2c7cbaa12d785", "title": "Niki de Saint Phalle", "text": "Niki de Saint Phalle (born Catherine-Marie-Agnès Fal de Saint Phalle, 29 October 193021 May 2002) was a French-American sculptor, painter, and filmmaker. She was one of the few women artists widely known for monumental sculpture.", "score": 40.5188}, {"id": "hp_doc_c85eef658c7c850731a716f69c669f32f1c2427c066738224cb7a19db24a2f5f", "title": "Number 23 Basketball Player", "text": "Number 23 Basketball Player is a sculpture by Niki de Saint Phalle.", "score": 34.6883}, {"id": "hp_doc_b8c00e19c8e8d965d5eb17e30c5f5471475b40ca6fde0ea1892cdc55b70c6890", "title": "Rio de Janeiro Cathedral", "text": "The Metropolitan Cathedral of Saint Sebastian (Portuguese: Catedral Metropolitana de São Sebastião ) better known as the \"Metropolitan Cathedral of Rio de Janeiro\" (\"Catedral Metropolitana do Rio de Janeiro )\" or as the Cathedral of St. Sebastian of Rio de Janeiro (\"Catedral de São Sebastião do Rio de Janeiro\" ), is the seat of the Roman Catholic Archdiocese of São Sebastião do Rio de Janeiro. The cathedral is the See of the Metropolitan Archbishops of the city of Rio de Janeiro, Brazil. The church is dedicated to Saint Sebastian, the patron saint of Rio de Janeiro.", "score": 13.9722}], "remaining_searches": 1}
